<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Course completion certificate</title>
<style>body{font-family:Georgia,serif;background:#f4f6ef;color:#193c32;margin:0;padding:40px}main{max-width:900px;margin:auto;background:white;border:8px double #49785c;padding:70px 35px;text-align:center}h1{font-size:44px}h2{font-size:32px}p{line-height:1.8}.code{font:12px monospace;overflow-wrap:anywhere}button,a{display:inline-block;margin:24px 12px;padding:12px 20px;color:inherit}nav{text-align:center}@media print{body{padding:0;background:white}nav{display:none}main{margin:20px}}@media(max-width:600px){body{padding:15px}main{padding:30px 15px}h1{font-size:30px}}</style></head>
<body><main><p>USP EDUCATION</p><h1>Certificate of Completion</h1><p>This certifies that</p><h2>{{ $enrollment->certificate_name }}</h2><p>has successfully completed</p><h2>{{ $enrollment->certificate_course }}</h2><p>Issued {{ $enrollment->completed_at->format('F j, Y') }}</p><p class="code">Certificate ID: {{ $enrollment->certificate_code }}</p></main><nav><button onclick="window.print()">Print / save as PDF</button><a href="{{ auth()->user()->is_admin ? route('admin.education.enrollments.show', $enrollment) : route('education.enrollments.show', $enrollment) }}">Return to enrollment</a></nav></body></html>
